begin;
create temp table _r(who text, leaderboard int, history int, history_others int);
grant all on _r to authenticated, anon;
do $$
declare u record;
begin
  for u in select id, email from auth.users where email in ('alice@example.com','bob@example.com') loop
    perform set_config('request.jwt.claims', json_build_object('sub',u.id,'role','authenticated')::text, true);
    set local role authenticated;
    insert into _r select u.email,
      (select count(*) from stats.member_activity),
      (select count(*) from stats.reading_history),
      (select count(*) from stats.reading_history where member_id <> u.id);
    reset role;
  end loop;
end $$;
select json_build_object(
  'members', (select json_agg(_r) from _r),
  'total_history', (select count(*) from stats.reading_history),
  'history_by_member', (select json_agg(x) from (select member_id, count(*) from stats.reading_history group by 1) x),
  'anon_schema_usage', has_schema_privilege('anon','stats','USAGE'),
  'anon_select_ma', has_table_privilege('anon','stats.member_activity','SELECT'),
  'anon_select_rh', has_table_privilege('anon','stats.reading_history','SELECT'),
  'auth_insert_rh', has_table_privilege('authenticated','stats.reading_history','INSERT')
) as result;
rollback;

